-- After 07 and RUNSTATS on APP.SECRET, which the agent user may not read: what the catalog and the monitor answer it.
-- The nine distribution statistics objects, whose COLVALUE holds stored values, are refused by the seed's revokes.
SELECT COUNT(*) FROM SYSIBM.SYSCOLDIST;
SELECT COUNT(*) FROM SYSIBM.SYSCOLDISTPARTITIONSTATS;
SELECT COUNT(*) FROM SYSIBM.SYSCOLGROUPDIST;
SELECT COUNT(*) FROM SYSCAT.COLDIST;
SELECT COUNT(*) FROM SYSCAT.COLDISTPARTITIONSTATS;
SELECT COUNT(*) FROM SYSCAT.COLGROUPDIST;
SELECT COUNT(*) FROM SYSSTAT.COLDIST;
SELECT COUNT(*) FROM SYSSTAT.COLDISTPARTITIONSTATS;
SELECT COUNT(*) FROM SYSSTAT.COLGROUPDIST;
-- The second highest and lowest value of each column stay readable in SYSCAT.COLUMNS, which the agent's catalog read needs.
SELECT COLNAME, HIGH2KEY, LOW2KEY FROM SYSCAT.COLUMNS WHERE TABSCHEMA = 'APP' AND TABNAME = 'SECRET';
SELECT V FROM APP.SECRET;
-- Statement history and other sessions are refused: the monitor needs an authority or EXECUTE the user does not hold.
SELECT COUNT(*) FROM SYSIBMADM.TOP_DYNAMIC_SQL;
SELECT COUNT(*) FROM SYSIBMADM.MON_CURRENT_SQL;
SELECT COUNT(*) FROM TABLE (MON_GET_PKG_CACHE_STMT(NULL, NULL, NULL, -2)) AS M;
SELECT COUNT(*) FROM TABLE (SYSPROC.SNAP_GET_DYN_SQL('', -1)) AS M;
SELECT COUNT(*) FROM TABLE (MON_GET_CONNECTION(NULL, -2)) AS M;
-- IBM masks the federated option settings, which can hold a remote password, from every user but SYSIBM.
SELECT VARCHAR(CONTROLNAME, 50) AS CONTROLNAME, VARCHAR(TABNAME, 20) AS TABNAME, COLNAME FROM SYSCAT.CONTROLS ORDER BY 1;
